package internal
import(
 "bytes"
 "encoding/json"
 "os"
 "path/filepath"
 "runtime"
 "strings"
 "testing"
 "time"
 "rawgraphcert/schema"
)
func baseModel()schema.Dataset{return schema.Dataset{SchemaVersion:"0.2",ID:"synthetic-only",TimeZone:"Etc/UTC",ServiceDate:"2026-10-20",Window:&schema.TimeWindow{Start:0,End:10000},Stops:[]schema.Stop{{ID:"a",Accessible:schema.Yes},{ID:"b",Accessible:schema.Yes},{ID:"c",Accessible:schema.Yes},{ID:"parent",Accessible:schema.Yes}},Trips:[]schema.Trip{{ID:"t",Accessible:schema.Yes}},Connections:[]schema.Connection{},Footpaths:[]schema.Footpath{},Transfers:[]schema.TransferRule{}}}
func baseQuery()schema.Query{return schema.Query{ID:"synthetic-query",Origin:"a",Destination:"c",Departure:100,LatestArrival:1000,MaxLegs:4,MaxBoardings:2,MaxWalkSeconds:10,Walking:&schema.WalkingLimits{Access:0,Direct:0,Egress:0,Transfer:0}}}
func laneRoot()string{_,f,_,_:=runtime.Caller(0);return filepath.Dir(filepath.Dir(f))}
func syntheticJob(t *testing.T,m schema.Dataset,q schema.Query)(Job,string){t.Helper();dir:=t.TempDir();mb:=canonical(m);mp:=filepath.Join(dir,"model.json");if e:=os.WriteFile(mp,mb,0644);e!=nil{t.Fatal(e)};qb:=canonical(q);qc,e:=canonicalRaw(qb);if e!=nil{t.Fatal(e)};wb:=canonical(map[string]any{"dataset_sha256":SHA(mb),"items":[]any{map[string]any{"query":json.RawMessage(qb)}}});wp:=filepath.Join(dir,"singleton.json");if e=os.WriteFile(wp,wb,0644);e!=nil{t.Fatal(e)};return Job{Window:"synthetic",Dataset:mp,DatasetSHA:SHA(mb),Queries:wp,QueriesSHA:SHA(wb),QueryID:q.ID,QuerySHA:SHA(qc),OriginalSlots:9},dir}
func guard()*Guard{return &Guard{Deadline:time.Now().Add(30*time.Second),MaxRows:10000}}
func candidate(t *testing.T,j Job)Candidate{t.Helper();c,e:=Produce(j,laneRoot(),"synthetic-protocol","synthetic-freeze",guard());if e!=nil{t.Fatal(e)};return c}
func verify(t *testing.T,j Job,c Candidate)(Verification,error){t.Helper();return Verify(j,laneRoot(),"synthetic-protocol","synthetic-freeze",canonical(c),guard())}
func ride(id,from,to string,seq int) schema.Connection{return schema.Connection{ID:id,TripID:"t",Sequence:seq,From:from,To:to,Departure:int64(100+seq*10),Arrival:int64(105+seq*10),Pickup:true,Dropoff:true}}
func walk(id,from,to string)schema.Footpath{return schema.Footpath{ID:id,From:from,To:to,Duration:999,Accessible:schema.No}}
func TestDisconnectedClosedCut(t *testing.T){m:=baseModel();m.Connections=[]schema.Connection{ride("x","a","b",0)};m.Footpaths=[]schema.Footpath{walk("back","b","a"),walk("outside","c","parent")};j,_:=syntheticJob(t,m,baseQuery());c:=candidate(t,j);v,e:=verify(t,j,c);if e!=nil{t.Fatal(e)};if v.Kind!="proven_empty_by_raw_stop_superset"||v.DirectScalarExecutions!=0||v.RawConnectionClosureRows!=1||v.RawFootpathClosureRows!=2{t.Fatalf("bad result %+v",v)};if !bytes.Equal(canonical(v.IndependentlyScanned),canonical(c.Projection)){t.Fatal("independent projection mismatch")}}
func TestSupersetNeverClaimsReachabilityFeasible(t *testing.T){for _,kind:=range []string{"forbidden_ride","walking_caps","same_trip_continuation"}{t.Run(kind,func(t *testing.T){m:=baseModel();switch kind{case "forbidden_ride":x:=ride("x","a","c",0);x.Pickup=false;x.Dropoff=false;x.Departure=2000;x.Arrival=2100;m.Connections=[]schema.Connection{x};m.Trips[0].Accessible=schema.No;case "walking_caps":m.Footpaths=[]schema.Footpath{walk("w","a","c")};case "same_trip_continuation":x,y:=ride("x","a","b",0),ride("y","b","c",1);y.Pickup=false;m.Connections=[]schema.Connection{x,y}};j,_:=syntheticJob(t,m,baseQuery());c:=candidate(t,j);if c.Kind!="unknown_raw_graph_destination_reachable"||len(c.ClosedSet)!=0||c.ClosedSetSHA!=""{t.Fatal("reachable must be UNKNOWN without certificate")};if _,e:=verify(t,j,c);e==nil{t.Fatal("verifier accepted reachable result")}})}}
func TestDirectedFootpathsAndNoParentTeleport(t *testing.T){m:=baseModel();m.Stops[0].ParentStation="parent";m.Stops[2].ParentStation="parent";m.Footpaths=[]schema.Footpath{walk("reverse","c","a")};j,_:=syntheticJob(t,m,baseQuery());c:=candidate(t,j);if _,e:=verify(t,j,c);e!=nil{t.Fatal(e)};if len(c.ClosedSet)!=1||c.ClosedSet[0]!="a"{t.Fatal("invented walking or station teleport")}}
func TestRepeatedEndpointRowsNotOmitted(t *testing.T){m:=baseModel();m.Footpaths=[]schema.Footpath{walk("x","a","b"),walk("y","a","b")};j,_:=syntheticJob(t,m,baseQuery());c:=candidate(t,j);v,e:=verify(t,j,c);if e!=nil{t.Fatal(e)};if v.RawFootpathClosureRows!=2||c.Projection.Counts.Footpaths!=2{t.Fatal("duplicate endpoint rows coalesced in raw projection")}}
func TestUnicodeEscapesNestedStrings(t *testing.T){m:=baseModel();m.Stops[0].ID="a\"\\{}[]\n雪☃";m.Stops[1].ID="b🙂";m.Footpaths=[]schema.Footpath{walk("w\"{nested:[\\]}",m.Stops[0].ID,m.Stops[1].ID)};q:=baseQuery();q.Origin=m.Stops[0].ID;j,_:=syntheticJob(t,m,q);c:=candidate(t,j);if _,e:=verify(t,j,c);e!=nil{t.Fatal(e)}}
func TestCertificateTamperingRejected(t *testing.T){m:=baseModel();m.Footpaths=[]schema.Footpath{walk("w","a","b")};j,_:=syntheticJob(t,m,baseQuery());good:=candidate(t,j);cases:=map[string]func(*Candidate){"omit_edge_count":func(c *Candidate){c.Projection.Counts.Footpaths=0},"wrong_projection":func(c *Candidate){c.Projection.FootpathsSHA="wrong"},"wrong_model":func(c *Candidate){c.DatasetSHA="wrong"},"wrong_query":func(c *Candidate){c.Query.RawSHA="wrong"},"wrong_protocol":func(c *Candidate){c.ProtocolSHA="wrong"},"missing_origin":func(c *Candidate){c.ClosedSet=[]string{"b"};c.ClosedSetSHA=SHA(canonical(c.ClosedSet))},"destination_present":func(c *Candidate){c.ClosedSet=[]string{"a","b","c"};c.ClosedSetSHA=SHA(canonical(c.ClosedSet))},"not_closed":func(c *Candidate){c.ClosedSet=[]string{"a"};c.ClosedSetSHA=SHA(canonical(c.ClosedSet))},"duplicate_stop":func(c *Candidate){c.ClosedSet=[]string{"a","a","b"};c.ClosedSetSHA=SHA(canonical(c.ClosedSet))},"unknown_stop":func(c *Candidate){c.ClosedSet=[]string{"a","b","invalid"};c.ClosedSetSHA=SHA(canonical(c.ClosedSet))},"wrong_set_hash":func(c *Candidate){c.ClosedSetSHA="wrong"},"wrong_source":func(c *Candidate){c.ProducerSourceSHA="wrong"}}
 for name,mut:=range cases{t.Run(name,func(t *testing.T){raw:=canonical(good);var c Candidate;if e:=json.Unmarshal(raw,&c);e!=nil{t.Fatal(e)};mut(&c);if _,e:=verify(t,j,c);e==nil{t.Fatal("tamper accepted")}})}}
func TestOriginEqualsDestinationRejected(t *testing.T){q:=baseQuery();q.Destination=q.Origin;j,_:=syntheticJob(t,baseModel(),q);if _,e:=Produce(j,laneRoot(),"p","f",guard());e==nil{t.Fatal("origin==destination accepted")}}
func TestInvalidNativeModelRefusedByIndependentVerifier(t *testing.T){m:=baseModel();m.Connections=[]schema.Connection{ride("x","a","b",2)};j,_:=syntheticJob(t,m,baseQuery());c:=candidate(t,j);if _,e:=verify(t,j,c);e==nil{t.Fatal("native invalid model accepted")}}
func TestMalformedRawModelsRejected(t *testing.T){mb:=string(canonical(baseModel()));cases:=map[string]string{"truncated":mb[:len(mb)-3],"extra_json":mb+"{}","duplicate_top":strings.Replace(mb,"\"id\":\"synthetic-only\"","\"id\":\"synthetic-only\",\"id\":\"evil\"",1),"duplicate_row":strings.Replace(mb,"\"id\":\"a\"","\"id\":\"a\",\"id\":\"b\"",1),"null_stops":strings.Replace(mb,"\"stops\":[", "\"stops\":null,\"unexpected\":[",1),"unknown_top":strings.Replace(mb,"{","{\"new_movement_semantics\":[],",1),"string_table":strings.Replace(mb,"\"connections\":[]","\"connections\":\"[]\"",1),"missing_table":strings.Replace(mb,"\"connections\":[],","",1),"bad_access_type":strings.Replace(mb,"\"accessible\":\"yes\"","\"accessible\":true",1),"escaped_duplicate":strings.Replace(mb,"\"id\":\"synthetic-only\"","\"id\":\"synthetic-only\",\"\\u0069d\":\"evil\"",1)}
 for name,raw:=range cases{t.Run(name,func(t *testing.T){p:=filepath.Join(t.TempDir(),"raw.json");if e:=os.WriteFile(p,[]byte(raw),0644);e!=nil{t.Fatal(e)};if _,_,_,_,e:=streamProjection(p,guard());e==nil{t.Fatal("streaming producer accepted malformed model")};if _,_,_,e:=fullDecode(p,guard());e==nil{t.Fatal("full verifier accepted malformed model")}})}}
func TestMalformedQueryTypesRejected(t *testing.T){raw:=canonical(baseQuery());for _,s:=range []string{strings.Replace(string(raw),"\"max_legs\":4","\"max_legs\":4.5",1),strings.Replace(string(raw),"\"accessible_only\":false","\"accessible_only\":null",1),strings.Replace(string(raw),"\"origin\":\"a\"","\"origin\":\"a\",\"origin\":\"b\"",1)}{if e:=checkQueryShape([]byte(s));e==nil{t.Fatal("invalid query type accepted")}}}
func TestBudgetAndCancellationProduceNoCertificate(t *testing.T){j,_:=syntheticJob(t,baseModel(),baseQuery());for _,g:=range []*Guard{{Deadline:time.Now().Add(-time.Second)},{Deadline:time.Now().Add(time.Minute),MaxRows:1}}{c,e:=Produce(j,laneRoot(),"p","f",g);if e==nil||c.Kind!=""{t.Fatal("budget hit emitted a candidate")}};c:=candidate(t,j);v,e:=Verify(j,laneRoot(),"synthetic-protocol","synthetic-freeze",canonical(c),&Guard{Deadline:time.Now().Add(-time.Second)});if e==nil||v.Kind!=""{t.Fatal("expired verification emitted proof")}}
func TestIndependentProjectionSmallAdversarialGraphs(t *testing.T){for mask:=0;mask<64;mask++{m:=baseModel();pairs:=[][2]string{{"a","b"},{"b","a"},{"b","c"},{"c","b"},{"parent","a"},{"c","parent"}};for i,p:=range pairs{if mask&(1<<i)!=0{m.Footpaths=append(m.Footpaths,walk(string(rune('w'+i)),p[0],p[1]))}};j,_:=syntheticJob(t,m,baseQuery());c:=candidate(t,j);if c.Kind=="candidate_raw_graph_closed_cut_not_yet_verified"{if _,e:=verify(t,j,c);e!=nil{t.Fatalf("mask %d: %v",mask,e)}}else if c.Kind!="unknown_raw_graph_destination_reachable"{t.Fatal("unexpected outcome")}}}
